/* Generated from the shared, reviewed editorial topic bank. */
globalThis.KaloreEssayIdeasData={"version":1,"reviewedAt":"2026-10-05","topics":[{"id":"leitura","title":"Leitura, livros e formação de leitores","axis":"Educação e cultura","proposals":["Desafios para democratizar o acesso à leitura e formar leitores no Brasil","Caminhos para ampliar o acesso à leitura no Brasil","Como aproximar jovens brasileiros dos livros e das bibliotecas"],"keywords":["biblioteca","livro","letramento","leitor","leitura escolar","mediação cultural","livraria"],"routes":[{"id":"territorio","label":"Território e mediação","thesis":"O acesso desigual a espaços de leitura e a pouca mediação no cotidiano escolar limitam a formação de leitores, sobretudo onde bibliotecas e atividades culturais são escassas.","arguments":[{"claim":"A distribuição desigual de bibliotecas e acervos restringe as oportunidades de leitura.","reason":"Quando o contato com livros depende da renda familiar ou do endereço, a leitura deixa de ser uma experiência acessível e vira vantagem acumulada.","example":"Uma turma pode comparar, em um mapa do município, a distância entre bairros e bibliotecas públicas; trate isso como exemplo hipotético, salvo pesquisa local.","question":"Que barreira concreta impede esse leitor de chegar a um livro?"},{"claim":"A leitura perde continuidade quando a escola a apresenta apenas como obrigação avaliativa.","reason":"Sem escolha, conversa e acompanhamento, muitos estudantes não encontram motivos para relacionar a leitura à própria vida.","example":"Um clube de leitura que permita escolher entre conto, quadrinho e crônica pode favorecer participação; avalie a experiência antes de afirmar resultado.","question":"Como a escola transforma o primeiro contato em hábito, sem impor um único gosto?"}],"intervention":{"agente":"Secretarias municipais e estaduais de Educação e Cultura","acao":"Criar circuitos permanentes de leitura em bairros com menor oferta cultural.","meio":"Integrar bibliotecas itinerantes, acervos acessíveis e rodas de leitura mediadas por profissionais em escolas e equipamentos comunitários.","finalidade":"Ampliar o acesso e fortalecer a formação de leitores em diferentes territórios."},"care":"Não reduza o problema a “falta de interesse”: investigue oferta, acessibilidade e experiências anteriores."},{"id":"pertencimento","label":"Pertencimento e diversidade","thesis":"Formar leitores exige reconhecer repertórios culturais plurais e oferecer materiais acessíveis; a ausência de representatividade pode afastar estudantes dos espaços de leitura.","arguments":[{"claim":"Acervos homogêneos silenciam experiências de parte dos leitores.","reason":"Quando livros não dialogam com diferentes origens, territórios, deficiências e modos de vida, a escola perde oportunidades de identificação e descoberta.","example":"Uma biblioteca escolar pode revisar, com os alunos, a variedade de autores, formatos e personagens do acervo — ação que precisa ser verificada na prática.","question":"Quem encontra sua experiência nos materiais oferecidos? Quem ainda fica de fora?"},{"claim":"Barreiras físicas e comunicacionais tornam uma biblioteca formalmente aberta, mas difícil de usar.","reason":"Pessoas com deficiência, leitores iniciantes e quem dispõe de pouco tempo precisam de condições concretas para participar.","example":"Audiolivros, texto acessível e horário ampliado são possibilidades; a escolha depende do público e da estrutura local.","question":"Que ajuste removeria a barreira identificada sem presumir as necessidades do público?"}],"intervention":{"agente":"Equipes das redes de ensino e bibliotecas públicas","acao":"Implantar curadoria participativa de acervos e planos de acessibilidade.","meio":"Ouvir estudantes e comunidades, diversificar formatos e acompanhar empréstimos e pedidos não atendidos para revisar a oferta.","finalidade":"Construir espaços de leitura representativos, acessíveis e acolhedores."},"care":"Evite usar representatividade como palavra decorativa; mostre qual barreira ela ajuda a enfrentar."}],"concepts":[{"title":"Letramento como prática social","text":"Observe os usos da leitura em situações reais, não apenas a decodificação de palavras."},{"title":"Mediação cultural","text":"Pense em quem aproxima o acervo do leitor, que escolhas oferece e como escuta sua resposta."}],"questions":["O argumento explica uma causa ou só repete que “ler é importante”?","A proposta chega aos leitores afetados e considera barreiras de acesso?","O exemplo é verificável ou está identificado como hipotético?"],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"digital","title":"Proteção de crianças no ambiente digital","axis":"Infância e juventude","proposals":["Caminhos para proteger crianças e adolescentes nos ambientes digitais brasileiros","Desafios para conciliar participação online e proteção da infância","Responsabilidade coletiva no ambiente digital vivido por crianças"],"keywords":["infância","criança","adolescente","eca digital","publicidade infantil","redes sociais","plataformas","tela"],"routes":[{"id":"responsabilidade","label":"Responsabilidade e desenho das plataformas","thesis":"A exposição de crianças a riscos digitais é ampliada por serviços projetados para prolongar engajamento e por respostas de proteção pouco claras para famílias e usuários.","arguments":[{"claim":"Mecanismos de recomendação e interação podem manter o público jovem exposto a conteúdo inadequado.","reason":"Recursos persuasivos, publicidade e coleta de dados tornam difícil para uma criança reconhecer riscos ou interromper o uso por conta própria.","example":"Uma análise de interface pode observar como recomendações e avisos aparecem em um perfil de teste; não atribua a uma empresa um efeito sem fonte.","question":"Que parte do funcionamento do serviço está fora do controle de uma criança?"},{"claim":"A responsabilidade é distribuída de forma desigual entre plataformas, responsáveis e escola.","reason":"Orientar famílias sem exigir transparência e proteção técnica transfere o peso para quem menos conhece o funcionamento dos sistemas.","example":"Uma oficina pode comparar configurações de privacidade e canais de denúncia de serviços usados pela comunidade, registrando limites encontrados.","question":"Qual ator tem poder real para reduzir a exposição e qual atribuição lhe cabe?"}],"intervention":{"agente":"Poder Público e empresas de tecnologia, com participação de famílias e especialistas","acao":"Fortalecer padrões de proteção por idade e canais de denúncia compreensíveis.","meio":"Publicar orientações em linguagem simples, revisar mecanismos de recomendação e encaminhar relatos a equipes treinadas, com transparência e respeito à privacidade.","finalidade":"Reduzir riscos digitais sem expulsar crianças dos espaços de aprendizagem e participação."},"care":"Não trate vigilância total nem proibição de internet como solução suficiente; considere privacidade e autonomia progressiva."},{"id":"alfabetizacao","label":"Educação digital e rede de cuidado","thesis":"A proteção online depende tanto de ferramentas preventivas quanto da capacidade de crianças e adultos reconhecerem riscos, conversar sobre eles e buscar ajuda.","arguments":[{"claim":"O letramento digital insuficiente dificulta identificar publicidade, manipulação e pedidos de dados.","reason":"Saber acessar um aplicativo não significa compreender seus incentivos ou avaliar a origem de uma mensagem.","example":"Uma turma pode classificar exemplos fictícios de anúncio, opinião e notícia antes de discutir como verificá-los.","question":"Que habilidade prática ajuda a criança a tomar uma decisão mais informada?"},{"claim":"O silêncio e o medo de punição podem atrasar a procura de apoio.","reason":"Quando adultos respondem com culpa ou confisco automático, jovens podem esconder situações de assédio ou exposição.","example":"Uma escola pode criar um protocolo de acolhimento com escuta reservada e contatos de proteção, validado com a comunidade escolar.","question":"Como acolher a revelação de um risco preservando a dignidade da criança?"}],"intervention":{"agente":"Escolas e redes de proteção da infância","acao":"Oferecer educação digital acompanhada de um fluxo seguro de acolhimento.","meio":"Realizar atividades com cenários fictícios, informar canais locais de ajuda e orientar profissionais sobre encaminhamento responsável.","finalidade":"Aumentar a autonomia para reconhecer riscos e facilitar a busca de apoio."},"care":"Evite culpabilizar crianças, famílias ou vítimas por falhas de desenho e moderação de serviços."}],"concepts":[{"title":"Proteção integral","text":"Analise deveres de cuidado de acordo com a idade e os direitos envolvidos."},{"title":"Letramento midiático","text":"Ensinar a perguntar quem publicou, com qual interesse e como conferir uma informação."}],"questions":["O texto distingue risco, responsabilidade e evidência?","A proteção preserva privacidade, participação e autonomia progressiva?","A intervenção inclui um canal claro para buscar ajuda?"],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"clima","title":"Crise climática e cidades vulneráveis","axis":"Meio ambiente","proposals":["Desafios para proteger populações vulneráveis dos desastres climáticos no Brasil","Caminhos para adaptar cidades brasileiras a eventos climáticos extremos","Desigualdade territorial e prevenção de desastres no Brasil"],"keywords":["enchente","chuva","seca","desastre","clima","aquecimento","adaptação urbana","defesa civil","risco ambiental"],"routes":[{"id":"prevencao","label":"Prevenção e desigualdade territorial","thesis":"Impactos climáticos tornam-se mais graves quando o planejamento urbano não reduz a exposição de moradias vulneráveis nem oferece alertas e rotas de evacuação acessíveis.","arguments":[{"claim":"Ocupação precária em áreas de risco expõe moradores a desastres previsíveis.","reason":"A desigualdade no acesso à moradia segura limita escolhas; responsabilizar quem vive nessas áreas esconde a falta de alternativas.","example":"Um estudo de caso municipal pode mapear moradias próximas a encostas ou cursos d’água, com dados e metodologia citados.","question":"Que decisão de planejamento aumentou a exposição, e que evidência local permite demonstrá-lo?"},{"claim":"Alertas e planos que não chegam a todos reduzem o tempo de resposta.","reason":"Avisos técnicos sem linguagem clara, redundância ou rota acessível podem deixar de orientar pessoas com necessidades diversas.","example":"Uma simulação escolar pode testar se uma família receberia um alerta em áreas com sinal instável; identifique-a como exercício.","question":"Quem pode não receber o aviso e qual alternativa de comunicação alcança essa pessoa?"}],"intervention":{"agente":"Prefeituras e órgãos de Defesa Civil","acao":"Mapear riscos e adotar planos locais de prevenção e resposta.","meio":"Combinar vistorias técnicas, alertas em múltiplos canais, rotas acessíveis e participação comunitária nos exercícios.","finalidade":"Reduzir a exposição ao risco e proteger a população antes e durante eventos extremos."},"care":"Não apresente um evento climático isolado como prova de uma tendência; use séries e fontes verificáveis."},{"id":"adaptacao","label":"Adaptação urbana e recuperação","thesis":"A vulnerabilidade climática persiste quando infraestrutura e políticas de recuperação ignoram diferenças de renda, mobilidade e acesso a serviços.","arguments":[{"claim":"Infraestrutura urbana impermeável e drenagem insuficiente podem agravar alagamentos.","reason":"A forma de ocupar o solo interfere no escoamento; obras precisam considerar bacia, manutenção e mudanças no uso do território.","example":"Compare projetos locais de drenagem e áreas verdes com mapas públicos, sem afirmar a eficácia antes de avaliar resultados.","question":"Qual mecanismo urbano conecta a intervenção proposta ao risco?"},{"claim":"A reconstrução após um desastre pode reproduzir a vulnerabilidade.","reason":"Se a recuperação não oferecer moradia segura, renda e participação, famílias podem retornar a áreas de risco por falta de alternativa.","example":"Uma audiência comunitária hipotética pode levantar necessidades de abrigo, transporte e documentação antes de planejar a resposta.","question":"O que a recuperação precisa garantir além de reparar prédios?"}],"intervention":{"agente":"Prefeituras e Defesa Civil, com apoio das áreas de habitação e assistência social","acao":"Integrar adaptação climática a obras urbanas e aos planos de reconstrução.","meio":"Priorizar áreas mapeadas, publicar critérios, ouvir moradores e monitorar manutenção das estruturas implementadas.","finalidade":"Diminuir danos e evitar que a recuperação reforce desigualdades existentes."},"care":"Diferencie mitigação das emissões, adaptação a impactos e resposta emergencial."}],"concepts":[{"title":"Vulnerabilidade socioambiental","text":"Cruza exposição a perigos com renda, moradia, infraestrutura e capacidade de resposta."},{"title":"Adaptação climática","text":"Preparar sistemas e territórios para impactos observados e projetados com base em avaliações."}],"questions":["O texto identificou a população e o risco concretos?","A solução também previne, em vez de só socorrer?","Cite dados climáticos apenas com fonte, período e recorte territorial."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"mental","title":"Saúde mental e hiperconexão","axis":"Saúde","proposals":["Desafios para o cuidado com a saúde mental de jovens em uma sociedade hiperconectada","Como promover bem-estar digital entre jovens no Brasil","Acolhimento e saúde mental de estudantes brasileiros"],"keywords":["ansiedade","saúde mental","jovem","hiperconexão","sono","bem-estar","rede social","atenção psicossocial"],"routes":[{"id":"acolhimento","label":"Acolhimento e acesso ao cuidado","thesis":"O sofrimento psíquico entre jovens pode ser agravado por pressões digitais e pela dificuldade de acessar escuta e atendimento contínuos.","arguments":[{"claim":"Comparação social e pressão por disponibilidade podem afetar o bem-estar.","reason":"Exposição repetida a conteúdos e expectativas pode influenciar hábitos e autoimagem, mas efeitos variam entre pessoas.","example":"Uma pesquisa escolar anônima e voluntária pode perguntar sobre hábitos sem coletar nomes ou diagnosticar estudantes.","question":"Que mecanismo foi observado e quais limites impedem generalizá-lo?"},{"claim":"Acolhimento tardio deixa estudantes sem apoio quando percebem sinais de sofrimento.","reason":"Estigma, filas e falta de articulação entre escola, família e rede de saúde dificultam a busca por ajuda qualificada.","example":"Um fluxo de encaminhamento escolar pode informar a quem recorrer sem transformar professor em terapeuta.","question":"Quem deve ouvir e encaminhar sem assumir uma função clínica que não lhe cabe?"}],"intervention":{"agente":"Secretarias de Saúde e Educação","acao":"Ampliar ações de promoção de bem-estar e acesso a atendimento psicossocial.","meio":"Capacitar equipes para acolhimento inicial, informar a rede disponível e articular encaminhamentos com profissionais habilitados.","finalidade":"Facilitar a busca precoce por cuidado apropriado e respeitar a singularidade dos jovens."},"care":"Não diagnostique leitor ou grupo, nem atribua todo sofrimento ao uso de telas."},{"id":"bem-estar","label":"Hábitos digitais e ambientes de estudo","thesis":"Promover bem-estar exige combinar autonomia para organizar hábitos de conexão com ambientes educacionais que não naturalizem exaustão ou isolamento.","arguments":[{"claim":"A disponibilidade permanente pode comprometer descanso e concentração.","reason":"Notificações e cobrança por resposta imediata fragmentam períodos de estudo e descanso, sobretudo quando não há regras coletivas.","example":"Uma turma pode pactuar horários sem notificações durante atividades e avaliar se a medida ajuda diferentes estudantes.","question":"A mudança depende apenas do indivíduo ou também das regras do ambiente?"},{"claim":"A escola pode abrir espaço para conversar sobre emoções sem estigmatizar.","reason":"Atividades de escuta e convivência ajudam a sinalizar caminhos de apoio, mas não substituem cuidado profissional.","example":"Uma roda com participação voluntária pode mapear fontes de estresse e encaminhar demandas sem expor relatos individuais.","question":"Como criar participação sem exigir que alguém revele informações privadas?"}],"intervention":{"agente":"Escolas, famílias e equipes de saúde locais","acao":"Adotar iniciativas de bem-estar digital e orientação de saúde mental.","meio":"Criar acordos de convivência, oficinas de uso consciente e materiais claros sobre serviços de atendimento da rede.","finalidade":"Reduzir barreiras à organização de hábitos e à procura de apoio qualificado."},"care":"Não recomende interromper tratamento nem troque informação clínica por opinião de internet."}],"concepts":[{"title":"Promoção da saúde","text":"Tratar bem-estar como resultado de condições, vínculos e acesso a serviços, não só vontade individual."},{"title":"Determinantes sociais","text":"Observar como renda, escola, território e relações alteram a possibilidade de cuidar da saúde."}],"questions":["A proposta respeita sigilo, voluntariedade e limite entre escola e serviço clínico?","Você evitou atribuir causalidade clínica sem pesquisa apropriada?","Que ambiente ou prática coletiva também precisa mudar?"],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"ia","title":"Inteligência artificial e desinformação","axis":"Tecnologia e informação","proposals":["Caminhos para enfrentar a desinformação amplificada pela inteligência artificial no Brasil","Desafios para identificar conteúdos sintéticos enganosos","Educação midiática e confiança em informação digital"],"keywords":["desinformação","inteligência artificial","deepfake","notícia falsa","conteúdo sintético","educação midiática","verificação digital"],"routes":[{"id":"verificacao","label":"Verificação e letramento midiático","thesis":"Conteúdos fabricados ou alterados por IA podem circular com rapidez, enquanto a baixa educação midiática dificulta verificar autoria, contexto e evidências.","arguments":[{"claim":"Imagens e áudios convincentes reduzem a confiança em sinais visuais familiares.","reason":"Ferramentas que geram conteúdo elevam a escala da produção; por isso, aparência não substitui confirmação por fonte independente.","example":"Uma atividade pode comparar uma mensagem inventada com um comunicado autêntico disponível em canal oficial.","question":"Que elemento foi checado além da aparência do conteúdo?"},{"claim":"A circulação repetida leva a pessoa a encontrar informação antes de saber avaliá-la.","reason":"Recomendações e compartilhamentos podem acelerar conteúdos emocionais; as condições variam por plataforma e contexto.","example":"Uma turma pode rastrear, em exemplos simulados, quem publicou primeiro e quais fontes documentam a alegação.","question":"Que evidência independente sustenta ou contradiz essa alegação?"}],"intervention":{"agente":"Redes de ensino e instituições de comunicação pública","acao":"Ensinar verificação de fontes, contexto e autoria em atividades permanentes.","meio":"Usar exemplos simulados, roteiros de checagem e acesso direto a canais oficiais, com revisão periódica do material.","finalidade":"Aumentar a capacidade de avaliar conteúdos antes de compartilhá-los."},"care":"Não declare que um detector de IA prova autoria ou falsidade: essas ferramentas podem errar."},{"id":"transparencia","label":"Transparência e circulação responsável","thesis":"Enfrentar desinformação exige mecanismos que informem como conteúdos sintéticos são apresentados e ofereçam respostas rastreáveis a relatos dos usuários.","arguments":[{"claim":"A ausência de contexto sobre conteúdo gerado ou editado dificulta a avaliação do público.","reason":"Sinais claros de origem podem apoiar a análise, embora não comprovem por si sós a verdade do conteúdo.","example":"Uma plataforma poderia testar avisos visíveis e um histórico de edição, medindo se usuários os percebem.","question":"O aviso identifica origem sem alegar certeza sobre a veracidade?"},{"claim":"A moderação sem explicação pode remover conteúdo legítimo ou falhar diante de manipulação.","reason":"Regras pouco claras impedem contestação e correção, enquanto decisões automatizadas também têm limites.","example":"Um fluxo de denúncia com justificativa e recurso pode ser avaliado por tipos de erro observados.","question":"Quem responde pelo erro e como o usuário pode pedir revisão?"}],"intervention":{"agente":"Plataformas digitais e autoridades competentes","acao":"Aumentar transparência sobre conteúdos sintéticos e canais de revisão.","meio":"Identificar anúncios e materiais alterados, publicar critérios e oferecer revisão humana em casos contestados.","finalidade":"Facilitar a avaliação responsável e corrigir decisões indevidas com prestação de contas."},"care":"Não trate qualquer uso de IA como engano nem confunda rótulo de origem com checagem factual."}],"concepts":[{"title":"Proveniência da informação","text":"Investigue autoria, publicação inicial, alterações e documentos que dão contexto."},{"title":"Alfabetização midiática","text":"Compare fontes independentes e diferencie fato verificável de interpretação ou opinião."}],"questions":["A ideia trata de origem, veracidade ou moderação? São questões distintas.","A proposta prevê contestação e correção de erro?","Não invente ferramentas, leis nem dados sobre circulação."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"inclusao","title":"Inclusão de pessoas com deficiência e neurodivergentes","axis":"Diversidade e direitos","proposals":["Desafios para garantir a participação social das pessoas neurodivergentes no Brasil","Como remover barreiras à participação de pessoas com deficiência","Inclusão escolar para além da matrícula"],"keywords":["acessibilidade","deficiência","neurodivergência","autismo","capacitismo","altas habilidades","inclusão escolar"],"routes":[{"id":"acesso","label":"Acessibilidade e remoção de barreiras","thesis":"Barreiras pedagógicas, comunicacionais e físicas limitam a participação social quando instituições não planejam ambientes acessíveis com escuta das pessoas atendidas.","arguments":[{"claim":"Materiais e serviços padronizados podem impedir acesso e autonomia.","reason":"Um ambiente inacessível transforma uma característica individual em exclusão produzida pela organização do espaço.","example":"Uma auditoria participativa pode percorrer um serviço público com usuários e registrar obstáculos encontrados.","question":"Quem participou do mapeamento e qual barreira foi documentada?"},{"claim":"A falta de formação e apoio contínuo enfraquece a inclusão escolar.","reason":"A matrícula não garante pertencimento quando adaptações e recursos são improvisados ou dependem de uma pessoa isolada.","example":"Uma equipe escolar pode planejar adaptações com o estudante e a família, revendo-as conforme o que funciona.","question":"Qual apoio é solicitado pela pessoa, em vez de presumido por terceiros?"}],"intervention":{"agente":"Gestores de serviços públicos e redes de ensino","acao":"Adotar planos de acessibilidade construídos com pessoas com deficiência.","meio":"Auditar barreiras, definir responsáveis e prazos, adequar materiais e avaliar a solução com quem a utiliza.","finalidade":"Aumentar autonomia, acesso e participação sem apagar diferenças individuais."},"care":"Não fale por todo um grupo nem presuma que uma única adaptação atende a todas as pessoas."},{"id":"capacitismo","label":"Representação e combate ao capacitismo","thesis":"Estereótipos e baixa participação de pessoas com deficiência nas decisões reforçam práticas que tratam autonomia e diferenças como exceção.","arguments":[{"claim":"Estereótipos reduzem pessoas a limitações ou a histórias de superação.","reason":"Representações repetidas podem limitar o que o público considera possível e obscurecer barreiras institucionais.","example":"Uma oficina pode analisar personagens e materiais públicos, verificando quem fala e que linguagem é usada.","question":"A representação mostra agência e diversidade ou serve só como inspiração para terceiros?"},{"claim":"Decisões sem consulta podem criar soluções incompatíveis com necessidades reais.","reason":"Projetos de acessibilidade funcionam melhor quando usuários participam desde a definição do problema.","example":"Um conselho local com participação remunerada de usuários pode revisar um serviço antes de sua implantação.","question":"A participação é contínua e influencia a decisão ou apenas valida algo pronto?"}],"intervention":{"agente":"Órgãos públicos, escolas e produtores de comunicação","acao":"Instituir participação de pessoas com deficiência no planejamento e na comunicação.","meio":"Criar consultas acessíveis, remunerar colaborações e publicar como as contribuições influenciaram medidas adotadas.","finalidade":"Diminuir barreiras e ampliar a representação de experiências diversas."},"care":"Use a linguagem que o próprio grupo prefere e confirme referências antes de citar diagnósticos."}],"concepts":[{"title":"Acessibilidade","text":"Avalie barreiras no ambiente, na comunicação, nos materiais e nas atitudes."},{"title":"Desenho universal","text":"Planejar produtos e espaços que sirvam ao maior número de pessoas, prevendo adaptações quando necessárias."}],"questions":["Quem definiu a barreira e participou da solução?","Matrícula ou acesso formal também significa participação efetiva?","Evite transformar deficiência em defeito individual a ser corrigido."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"educacao","title":"Alfabetização e desigualdade educacional","axis":"Educação e cultura","proposals":["Caminhos para garantir a alfabetização plena e reduzir desigualdades educacionais no Brasil","Desafios à alfabetização de crianças no Brasil","Como fortalecer a permanência e a aprendizagem escolar"],"keywords":["alfabetização","analfabetismo","evasão","abandono escolar","aprendizagem","permanência escolar","alfabetismo"],"routes":[{"id":"apoio","label":"Apoio pedagógico e desigualdade","thesis":"Diferenças nas condições de acesso a materiais, tempo de aprendizagem e apoio pedagógico dificultam garantir alfabetização contínua a todos os estudantes.","arguments":[{"claim":"A aprendizagem não avança no mesmo ritmo quando faltam acompanhamento e materiais acessíveis.","reason":"Turmas heterogêneas precisam de diagnóstico pedagógico e apoio sem estigmatizar quem aprende em outro ritmo.","example":"A escola pode analisar produções de escrita para planejar grupos temporários de apoio, revendo o plano após nova avaliação.","question":"Como o acompanhamento identifica necessidade sem rotular a criança?"},{"claim":"Desigualdades fora da sala de aula alteram as condições de frequência e estudo.","reason":"Transporte, alimentação, responsabilidades de cuidado e acesso a livros podem interferir na permanência.","example":"Uma equipe local pode conversar com famílias, preservando sigilo, para identificar obstáculos à frequência.","question":"A proposta atua sobre o obstáculo identificado ou exige que a família o resolva sozinha?"}],"intervention":{"agente":"Redes públicas de ensino","acao":"Oferecer acompanhamento pedagógico contínuo e busca ativa acolhedora.","meio":"Formar equipes para monitorar aprendizagem e frequência, organizar apoio e articular encaminhamentos sociais quando necessário.","finalidade":"Garantir condições de continuidade e de desenvolvimento das aprendizagens."},"care":"Não use notas isoladas como prova de incapacidade nem equipare falta a desinteresse."},{"id":"permanencia","label":"Permanência e equidade","thesis":"Políticas uniformes de alfabetização têm alcance limitado quando desconsideram a diversidade linguística, territorial e de necessidades dos estudantes.","arguments":[{"claim":"Materiais pouco conectados à realidade da turma podem reduzir participação.","reason":"Conteúdos e exemplos que ignoram línguas, territórios e experiências locais dificultam a construção de sentido.","example":"Professores podem selecionar textos de diferentes gêneros e contextos com participação dos alunos.","question":"O material acrescenta repertório e também reconhece o que a turma já conhece?"},{"claim":"Descontinuidade de programas e de equipes enfraquece ações de longo prazo.","reason":"Formação pontual sem tempo de planejamento não acompanha mudanças no aprendizado nem apoia professores.","example":"Uma rede pode manter horários regulares de formação colaborativa e acompanhar indicadores por escola.","question":"Qual acompanhamento permite corrigir o programa antes do fim do ano?"}],"intervention":{"agente":"Secretarias de Educação e equipes escolares","acao":"Manter programas de alfabetização com formação e monitoramento territorial.","meio":"Reservar tempo de planejamento, adequar recursos aos contextos e revisar resultados com profissionais e famílias.","finalidade":"Reduzir desigualdades de oportunidade e apoiar práticas sustentáveis."},"care":"Diferencie oferta da escola, condições sociais e decisões de política pública; não atribua o problema a um só ator."}],"concepts":[{"title":"Direito à aprendizagem","text":"Verifique frequência, participação, materiais e apoio, além do acesso à matrícula."},{"title":"Avaliação formativa","text":"Usar evidências do percurso para ajustar o ensino, sem confundi-las com rótulo definitivo."}],"questions":["O argumento identifica uma barreira específica ao aprendizado?","O texto apresenta a criança como sujeito, sem culpabilizar famílias?","Qual evidência de contexto sustenta a leitura sobre a rede ou a escola?"],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"trabalho","title":"Trabalho, informalidade e proteção social","axis":"Trabalho","proposals":["Desafios para garantir trabalho digno diante das novas relações de emprego no Brasil","Proteção social diante do trabalho mediado por plataformas","Reconhecimento e valorização do trabalho de cuidado no Brasil"],"keywords":["trabalho","informalidade","plataforma","entregador","cuidado","proteção social","uberização","emprego"],"routes":[{"id":"protecoes","label":"Proteção e previsibilidade","thesis":"Relações de trabalho mediadas por plataformas podem combinar controle tecnológico e baixa previsibilidade de renda, enquanto a proteção social nem sempre acompanha a realidade ocupacional.","arguments":[{"claim":"A gestão por aplicativos pode reduzir a transparência sobre distribuição de tarefas e remuneração.","reason":"Sem conhecer critérios e canais de contestação, trabalhadores têm dificuldade para planejar renda ou corrigir erros.","example":"Entrevistas consentidas e dados públicos podem comparar relatos sobre uma atividade, indicando período e limites da amostra.","question":"Como o trabalhador pode conhecer e contestar uma decisão que afeta sua atividade?"},{"claim":"A renda variável aumenta a dificuldade de planejar proteção diante de doença ou acidente.","reason":"Instabilidade e vínculos diversos podem tornar contribuições e acesso a direitos menos previsíveis.","example":"Um orçamento hipotético pode comparar um mês de demanda alta e outro baixo, sem fingir que representa toda a categoria.","question":"Que mecanismo protege a pessoa quando a renda varia ou o trabalho é interrompido?"}],"intervention":{"agente":"Poder Público e atores econômicos envolvidos","acao":"Ampliar transparência e proteção adequada às formas contemporâneas de trabalho.","meio":"Publicar regras compreensíveis de remuneração, oferecer contestação e estudar mecanismos de proteção com participação dos trabalhadores.","finalidade":"Promover condições dignas, previsíveis e seguras."},"care":"Evite declarar vínculo jurídico ou atribuir direitos legais específicos sem conferir a legislação atual."},{"id":"reconhecimento","label":"Cuidado e invisibilidade","thesis":"A concentração do trabalho de cuidado em famílias e ocupações pouco reconhecidas pode ampliar desigualdades e restringir a participação social de quem cuida.","arguments":[{"claim":"O cuidado não remunerado consome tempo e pode limitar estudo e emprego.","reason":"Quando políticas e serviços não apoiam famílias, tarefas se concentram e tornam menos visível sua contribuição.","example":"Um diário de tempo voluntário e anônimo pode revelar como tarefas se distribuem em uma amostra local.","question":"Que dado mostraria quem realiza o cuidado e quanto tempo dedica?"},{"claim":"O trabalho de cuidado remunerado pode ficar invisível nas estatísticas e no debate público.","reason":"Baixo reconhecimento dificulta formular condições e serviços compatíveis com a importância da atividade.","example":"Uma análise pode comparar como diferentes funções de cuidado aparecem em materiais e debates locais, citando suas fontes.","question":"Que experiência está ausente e que evidência ajuda a torná-la visível?"}],"intervention":{"agente":"Órgãos de assistência social e políticas de trabalho","acao":"Reconhecer necessidades de cuidado na oferta de serviços e proteção.","meio":"Consultar trabalhadores e famílias, ampliar informação sobre serviços locais e monitorar acesso por território.","finalidade":"Distribuir melhor as responsabilidades e valorizar quem cuida."},"care":"Não presuma que todas as mulheres ou famílias vivem a mesma divisão de tarefas."}],"concepts":[{"title":"Proteção social","text":"Examine mecanismos que ajudam pessoas a enfrentar doença, acidentes ou perda de renda."},{"title":"Economia do cuidado","text":"Investigue como atividades remuneradas e não remuneradas sustentam a vida e são distribuídas."}],"questions":["O texto separa análise social de afirmações sobre o que a lei prevê hoje?","A solução foi construída com quem trabalha ou cuida?","Um exemplo hipotético não se torna estatística só por ser plausível."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"genero","title":"Violência de gênero e invisibilidade feminina","axis":"Diversidade e direitos","proposals":["Caminhos para enfrentar a violência de gênero e a radicalização nos ambientes digitais","Desafios para proteger mulheres da violência no espaço público e digital","Invisibilidade do trabalho de cuidado e desigualdade de gênero"],"keywords":["violência de gênero","violência contra a mulher","misoginia","mulheres","cuidado","assédio","discriminação"],"routes":[{"id":"acolher","label":"Prevenção e redes de proteção","thesis":"A persistência da violência de gênero é agravada por normas que a naturalizam e por obstáculos para encontrar acolhimento e proteção adequados.","arguments":[{"claim":"Estereótipos podem normalizar comportamentos de controle e intimidação.","reason":"Piadas, ameaças e culpabilização diluem a percepção de violência e tornam mais difícil pedir ajuda.","example":"Uma análise de campanhas ou materiais escolares pode identificar mensagens que reproduzem ou questionam estereótipos.","question":"A linguagem responsabiliza quem sofreu violência ou questiona a conduta de quem a pratica?"},{"claim":"A falta de informação sobre serviços dificulta o acesso à proteção.","reason":"Mesmo quando há canais, desconhecê-los ou recear exposição pode impedir sua utilização.","example":"Uma rede local pode testar se materiais de orientação informam contatos atualizados e acessíveis.","question":"O encaminhamento protege sigilo e considera a segurança da pessoa?"}],"intervention":{"agente":"Redes locais de proteção, saúde e educação","acao":"Divulgar fluxos de acolhimento e fortalecer ações preventivas.","meio":"Produzir orientação acessível com serviços locais verificados, treinar equipes de primeira escuta e revisar encaminhamentos com especialistas.","finalidade":"Facilitar o acesso a apoio seguro e reduzir a naturalização da violência."},"care":"Não peça que a vítima confronte o agressor como condição para receber acolhimento."},{"id":"ambiente-digital","label":"Assédio online e responsabilidade","thesis":"A violência contra mulheres no espaço digital pode ser ampliada pela repetição de ataques e por canais de denúncia difíceis de acessar.","arguments":[{"claim":"Conteúdos misóginos podem intimidar e restringir a participação online.","reason":"A frequência e o alcance de ataques afetam a liberdade de expressão e a decisão de permanecer em comunidades digitais.","example":"Uma auditoria pode medir tempos de resposta de canais públicos a relatos simulados, sem expor vítimas reais.","question":"Que participação foi inibida e como isso foi documentado?"},{"claim":"A remoção de conteúdo sem cuidado pode apagar provas ou expor ainda mais quem denuncia.","reason":"Resposta responsável precisa oferecer orientação, preservar escolhas e proteger dados pessoais.","example":"Um fluxo de denúncia pode informar opções de bloqueio, registro e recurso antes de qualquer publicação adicional.","question":"A medida devolve poder de decisão à pessoa afetada?"}],"intervention":{"agente":"Plataformas e serviços públicos de acolhimento","acao":"Tornar canais de denúncia acessíveis e conectar plataformas a orientação segura.","meio":"Explicar opções, reduzir etapas, proteger dados e informar serviços de apoio verificados sem exigir exposição pública.","finalidade":"Reduzir barreiras à denúncia e apoiar escolhas seguras."},"care":"Não minimize ameaça por ocorrer na internet nem publique detalhes que identifiquem uma vítima."}],"concepts":[{"title":"Violência baseada em gênero","text":"Analise padrões de poder e barreiras de proteção sem presumir histórias individuais."},{"title":"Escuta e sigilo","text":"Acolher inclui preservar a autonomia e evitar a circulação desnecessária de relatos."}],"questions":["A proposta se coordena com serviços de apoio existentes?","Você evita culpabilizar ou expor a vítima?","Se usar números, verifique série, definição, fonte e ano."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"moradia","title":"Moradia e população em situação de rua","axis":"Cidadania e sociedade","proposals":["Desafios para assegurar moradia digna e proteção social à população em situação de rua","Caminhos para enfrentar o déficit habitacional urbano","Acolhimento e acesso a serviços pela população em situação de rua"],"keywords":["moradia","habitação","situação de rua","déficit habitacional","aluguel","gentrificação","acolhimento"],"routes":[{"id":"servicos","label":"Moradia e acesso a serviços","thesis":"A insegurança habitacional é agravada pela oferta limitada de soluções estáveis e por barreiras para acessar documentação, saúde e assistência social.","arguments":[{"claim":"Sem moradia estável, atividades cotidianas e acesso a serviços tornam-se mais difíceis.","reason":"Guardar documentos, descansar e se deslocar para atendimento exige recursos que podem faltar a quem não tem endereço fixo.","example":"Um mapa de serviços e horários de atendimento do município pode mostrar distâncias a percorrer, quando construído com usuários.","question":"Que tarefa básica ou serviço exige um endereço ou deslocamento difícil?"},{"claim":"Atendimentos fragmentados podem obrigar a pessoa a reconstruir sua história em vários locais.","reason":"Falta de coordenação e acolhimento com estigma enfraquece a continuidade do cuidado.","example":"Uma rede local pode desenhar um fluxo de encaminhamento que evite repetir cadastro e exposição.","question":"A intervenção reduz uma etapa ou apenas cria mais um serviço isolado?"}],"intervention":{"agente":"Municípios e serviços de assistência, habitação e saúde","acao":"Articular acolhimento com acesso a moradia e serviços essenciais.","meio":"Mapear barreiras com participação de usuários, integrar encaminhamentos e acompanhar a continuidade do atendimento.","finalidade":"Fortalecer proteção social e acesso a direitos com respeito à dignidade."},"care":"Não descreva população em situação de rua como homogênea nem confunda assistência emergencial com política habitacional."},{"id":"habitação","label":"Planejamento e permanência","thesis":"O acesso precário à habitação pode se perpetuar quando a política urbana não articula disponibilidade de moradias, permanência e infraestrutura nos bairros.","arguments":[{"claim":"A distância entre habitação e serviços pode criar custos e isolamento.","reason":"Moradia acessível distante de trabalho, escola ou transporte impõe barreiras que podem comprometer permanência.","example":"Comparar mapas públicos de transporte e equipamentos em projetos habitacionais ajuda a avaliar localização.","question":"O plano oferece moradia em território conectado a quê?"},{"claim":"Despejos e valorização imobiliária podem deslocar residentes de áreas com serviços.","reason":"Sem participação e proteção à permanência, melhorias urbanas podem beneficiar uns enquanto afastam outros.","example":"Uma consulta pública pode levantar necessidades de moradores antes de uma obra, registrando propostas e respostas.","question":"Quem decide sobre a mudança e como moradores participam?"}],"intervention":{"agente":"Prefeituras e gestores de planejamento urbano","acao":"Planejar moradia junto com infraestrutura, transporte e serviços.","meio":"Publicar critérios de localização, ouvir residentes e acompanhar custos de deslocamento e permanência após a entrega.","finalidade":"Aumentar acesso à moradia digna sem aprofundar segregação urbana."},"care":"Não trate remoção como solução de visibilidade do problema; explique alternativas e proteção a direitos."}],"concepts":[{"title":"Direito à cidade","text":"Considere acesso a moradia, transporte, serviços, cultura e participação no território."},{"title":"Intersetorialidade","text":"Serviços de áreas distintas precisam coordenar encaminhamento e acompanhamento."}],"questions":["O texto diferencia resposta imediata e garantia duradoura de moradia?","Moradores participaram da definição da medida?","Evite usar “retirar das ruas” sem perguntar para onde, com que escolha e apoio."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"ciencia","title":"Ciência, saúde pública e automedicação","axis":"Saúde","proposals":["Caminhos para fortalecer a confiança na ciência e a informação responsável em saúde no Brasil","Desafios para comunicar evidências científicas à população","Como prevenir os riscos da automedicação com informação confiável"],"keywords":["ciência","saúde pública","automedicação","vacina","divulgação científica","evidência","desinformação em saúde"],"routes":[{"id":"comunicacao","label":"Comunicação acessível e fontes","thesis":"A confiança em informações de saúde pode ser enfraquecida pela comunicação pouco acessível e pela circulação de alegações sem avaliação de evidências.","arguments":[{"claim":"Linguagem técnica pode excluir parte do público de debates que afetam seu cuidado.","reason":"Quando dúvidas ficam sem resposta compreensível, materiais simplificados por fontes duvidosas ocupam o espaço.","example":"Uma unidade de saúde pode testar dois formatos de orientação com leitores voluntários e revisar trechos confusos.","question":"Quem consegue compreender a mensagem e que dúvida permanece aberta?"},{"claim":"Mensagens sem indicação de fonte ou contexto dificultam a checagem.","reason":"Uma conclusão científica precisa de autoria, escopo e limitações para ser interpretada com responsabilidade.","example":"Uma atividade pode comparar uma postagem viral com a publicação ou nota institucional que ela cita.","question":"A fonte sustenta exatamente a afirmação compartilhada?"}],"intervention":{"agente":"Instituições de pesquisa e redes de saúde","acao":"Ampliar divulgação científica em linguagem acessível e verificável.","meio":"Produzir materiais com profissionais de comunicação e saúde, identificar fontes e atualizar respostas a dúvidas frequentes.","finalidade":"Ajudar o público a compreender evidências e localizar orientação confiável."},"care":"A redação não substitui avaliação profissional; evite prescrever ou recomendar tratamento."},{"id":"autonomia","label":"Automedicação e acesso à orientação","thesis":"A automedicação pode envolver busca por alívio rápido em contextos de acesso difícil à orientação, além de circulação de conselhos sem qualificação.","arguments":[{"claim":"A demora ou dificuldade de acesso pode levar pessoas a buscar soluções por conta própria.","reason":"Tempo, custo e distância influenciam decisões; isso não torna segura uma orientação sem avaliação adequada.","example":"Um caso hipotético pode descrever alguém recorrendo a postagem viral diante de uma dúvida não atendida.","question":"Que barreira de acesso aparece antes da decisão?"},{"claim":"Recomendações virais podem apagar diferenças entre pessoas e situações clínicas.","reason":"Uma experiência individual não demonstra segurança ou eficácia para outras pessoas.","example":"Uma oficina pode analisar exemplos simulados e marcar promessas que não citam fonte ou população estudada.","question":"Que parte da mensagem tenta generalizar uma experiência?"}],"intervention":{"agente":"Redes públicas de saúde e instituições de divulgação científica","acao":"Ampliar orientação pública acessível sobre evidências e serviços de saúde.","meio":"Reunir perguntas frequentes, indicar canais locais de atendimento e atualizar conteúdos revisados por profissionais habilitados.","finalidade":"Facilitar decisões informadas e reduzir dependência de recomendações sem contexto."},"care":"Não reproduza doses, tratamentos ou alegações clínicas não verificadas."}],"concepts":[{"title":"Evidência científica","text":"Pergunte qual método, população, incerteza e revisão sustentam uma afirmação."},{"title":"Risco relativo e contexto","text":"Uma afirmação responsável informa para quem, quando e em que condições se aplica."}],"questions":["O texto distingue dúvida legítima de desinformação deliberada?","A fonte consultada é compatível com a afirmação usada?","Não transforme associação observada em causa comprovada."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"juventude","title":"Violência e oportunidades para a juventude","axis":"Infância e juventude","proposals":["Desafios para garantir segurança e oportunidades à juventude brasileira","Como ampliar o acesso de jovens à cultura, estudo e trabalho","Prevenção da violência por meio de proteção e oportunidades"],"keywords":["juventude","violência juvenil","primeiro emprego","oportunidade","jovem","cultura","esporte","evasão escolar"],"routes":[{"id":"oportunidade","label":"Oportunidades e proteção","thesis":"A exposição de jovens à violência é influenciada por desigualdades de acesso a direitos e por respostas públicas que chegam de maneira desigual aos territórios.","arguments":[{"claim":"A ausência de espaços de convivência e oportunidades restringe alternativas de participação.","reason":"Escola, esporte, cultura e trabalho digno podem ampliar escolhas quando acessíveis e contínuos.","example":"Um inventário comunitário pode mapear quadras, bibliotecas e programas por horário e bairro.","question":"A oportunidade existe no papel ou é acessível no horário e território do jovem?"},{"claim":"Políticas centradas apenas em punição deixam prevenção e proteção em segundo plano.","reason":"Abordagens sem escuta podem afastar jovens dos serviços capazes de responder a riscos e necessidades.","example":"Um conselho juvenil pode avaliar acolhimento em equipamentos públicos e propor ajustes acompanhados.","question":"A medida protege o jovem e também reconhece sua voz?"}],"intervention":{"agente":"Gestores municipais de Educação, Cultura e Assistência Social","acao":"Criar percursos locais de acesso a atividades e proteção para jovens.","meio":"Articular equipamentos existentes, reservar vagas e horários acessíveis e acompanhar participação com conselhos juvenis.","finalidade":"Ampliar escolhas, pertencimento e acesso a apoio nos territórios."},"care":"Evite associar juventude, raça ou território à criminalidade sem evidências; proteja grupos contra estigmas."},{"id":"trabalho","label":"Permanência escolar e transição","thesis":"Permanecer na escola e chegar ao primeiro emprego digno pode ser difícil quando renda, responsabilidades familiares e formação profissional se chocam.","arguments":[{"claim":"A necessidade de renda pode competir com tempo de estudo e descanso.","reason":"Sem apoio compatível, a transição para o trabalho pode ampliar abandono escolar ou ocupações instáveis.","example":"Uma pesquisa voluntária pode perguntar a estudantes sobre horários de trabalho e barreiras de transporte.","question":"Como a proposta considera rotina e renda em vez de simplesmente exigir disponibilidade?"},{"claim":"Informações e redes de acesso ao primeiro emprego são distribuídas de forma desigual.","reason":"Orientação profissional e experiências práticas ajudam quando acessíveis a diferentes escolas e bairros.","example":"Uma escola pode convidar profissionais de setores variados e oferecer oficinas abertas a turmas diversas.","question":"Quem não recebe a informação e como alcançar esse público?"}],"intervention":{"agente":"Escolas, serviços de juventude e empregadores participantes","acao":"Oferecer orientação e experiências de transição escola-trabalho compatíveis com a permanência escolar.","meio":"Articular oficinas, informação acessível e oportunidades com horários previsíveis e salvaguardas para jovens.","finalidade":"Apoiar autonomia e formação sem afastar estudantes da escola."},"care":"Não transforme “oportunidade” em promessa de vaga ou solução individual para desemprego estrutural."}],"concepts":[{"title":"Prevenção social","text":"Agir nas condições que expõem pessoas a riscos e fortalecer fatores de proteção coletiva."},{"title":"Participação juvenil","text":"Jovens conhecem obstáculos do cotidiano e precisam influenciar a política que os afeta."}],"questions":["O texto evita associar automaticamente pobreza e violência?","A oportunidade descrita tem horário, acesso e responsável definidos?","Consulte fonte atual se citar estatísticas de violência."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"democracia","title":"Participação social e cidadania","axis":"Cidadania e sociedade","proposals":["Caminhos para ampliar a participação social na construção de políticas públicas brasileiras","Acesso à informação e participação cidadã no Brasil","Desafios à representação de diferentes grupos nos espaços de decisão"],"keywords":["cidadania","participação","representação política","acesso à informação","políticas públicas","registro civil","conselho local"],"routes":[{"id":"acesso-informacao","label":"Informação e canais de participação","thesis":"A desigualdade no acesso a informações claras e a espaços de decisão limita a participação cidadã de grupos menos representados.","arguments":[{"claim":"Consultas públicas pouco acessíveis afastam pessoas afetadas pelas decisões.","reason":"Horários, linguagem técnica e ausência de devolutiva fazem a participação parecer simbólica.","example":"Uma audiência local pode publicar contribuições recebidas e explicar quais foram incorporadas.","question":"Quem pôde participar e o que aconteceu com as contribuições?"},{"claim":"A desinformação sobre serviços e decisões dificulta o exercício da cidadania.","reason":"Informações dispersas sobre prazos e canais aumentam erros e reduzem confiança.","example":"Um município pode consolidar orientações em uma página simples, com versão impressa em equipamentos públicos.","question":"A informação chega também a quem tem conexão limitada?"}],"intervention":{"agente":"Gestores públicos e conselhos de políticas","acao":"Tornar consultas e informações públicas acessíveis e transparentes.","meio":"Oferecer mais de um canal, horário previsível, linguagem simples e devolutiva que registre encaminhamentos.","finalidade":"Ampliar participação informada e mostrar como as contribuições foram consideradas."},"care":"Participação não se resume a comparecer: importa influência, diversidade e retorno."},{"id":"representacao","label":"Representação e escuta","thesis":"Quando os espaços de decisão não refletem a diversidade das comunidades afetadas, políticas podem deixar barreiras importantes sem resposta.","arguments":[{"claim":"Custos de participação e critérios de entrada podem excluir pessoas com menos tempo ou recursos.","reason":"Deslocamento, cuidado de familiares e reuniões sem acessibilidade limitam quem consegue permanecer.","example":"Um conselho pode testar participação remota e apoio de transporte, avaliando quem passa a participar.","question":"Que custo concreto impede alguém de falar e qual ajuste o reduz?"},{"claim":"Falta de retorno desestimula contribuições futuras.","reason":"A pessoa que compartilha uma experiência quer saber se a informação foi analisada e o que mudou.","example":"Uma consulta pode divulgar uma matriz pública com temas recebidos, decisões e justificativas.","question":"Como a instituição demonstra que escutou mesmo quando não adota uma sugestão?"}],"intervention":{"agente":"Órgãos responsáveis por consultas e conselhos locais","acao":"Revisar as condições de participação e criar devolutivas públicas.","meio":"Identificar barreiras com grupos afetados, adaptar canais e explicar decisões em linguagem acessível.","finalidade":"Fortalecer a confiança e a representatividade na elaboração de políticas."},"care":"Não trate toda consulta como retrato da opinião de toda a população."}],"concepts":[{"title":"Transparência pública","text":"Informação acessível e rastreável permite que a sociedade acompanhe decisões."},{"title":"Representatividade","text":"Observe quem participa, quais experiências chegam e como são consideradas."}],"questions":["Que grupo afetado ainda não está representado?","A instituição explica o destino das contribuições?","Não use “o povo pensa” com base em uma amostra pequena."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"idosos","title":"Envelhecimento e combate ao etarismo","axis":"Diversidade e direitos","proposals":["Desafios para promover autonomia e inclusão da população idosa no Brasil","Como ampliar a inclusão digital de pessoas idosas","Combate ao etarismo nas relações de trabalho e na sociedade"],"keywords":["idoso","envelhecimento","etarismo","inclusão digital","autonomia","acessibilidade","cuidado"],"routes":[{"id":"autonomia","label":"Autonomia e redes de cuidado","thesis":"A participação social de pessoas idosas é limitada por ambientes pouco acessíveis, estereótipos sobre envelhecimento e apoio insuficiente a diferentes necessidades de cuidado.","arguments":[{"claim":"Estereótipos podem tratar pessoas idosas como um grupo sem autonomia ou planos próprios.","reason":"Quando instituições presumem incapacidade, limitam oportunidades de participação e decisão.","example":"Uma pesquisa de linguagem em anúncios ou serviços pode verificar como idade e autonomia são retratadas.","question":"A pessoa idosa é consultada sobre a decisão ou apenas descrita por terceiros?"},{"claim":"Barreiras em transporte, serviços e espaços digitais reduzem acesso cotidiano.","reason":"Interfaces e rotinas projetadas sem diversidade de usuários tornam tarefas simples dependentes de terceiros.","example":"Uma avaliação voluntária de um serviço digital pode reunir usuários de diferentes níveis de familiaridade.","question":"Qual etapa do serviço pode ganhar acessibilidade sem exigir que alguém peça ajuda?"}],"intervention":{"agente":"Gestores municipais e prestadores de serviços","acao":"Revisar acessibilidade e participação em serviços usados por pessoas idosas.","meio":"Realizar testes com usuários, oferecer atendimento em mais de um canal e capacitar equipes para escuta respeitosa.","finalidade":"Aumentar autonomia e convivência, respeitando escolhas individuais."},"care":"Não trate idade como diagnóstico nem presuma que toda pessoa idosa usa ou rejeita tecnologia."},{"id":"participacao","label":"Idade, trabalho e convivência","thesis":"Práticas etaristas podem excluir pessoas idosas de relações de trabalho, convivência e aprendizagem mesmo quando desejam participar.","arguments":[{"claim":"Seleção e formação podem reproduzir pressupostos sobre idade e capacidade.","reason":"Exigências sem relação com a função e oportunidades concentradas em poucos grupos podem reforçar exclusão.","example":"Uma organização pode comparar quem recebe convites de formação por faixa etária, respeitada a privacidade.","question":"Que critério avalia competência e qual apenas presume limitação?"},{"claim":"A convivência intergeracional fica restrita quando serviços separam públicos por idade.","reason":"Troca entre gerações pode surgir de projetos comuns com papéis e respeito mútuo.","example":"Uma atividade de troca de saberes pode ser construída com participantes que escolhem o que desejam compartilhar.","question":"Quem define o objetivo e o benefício esperado da atividade?"}],"intervention":{"agente":"Empregadores e gestores de equipamentos comunitários","acao":"Revisar regras de acesso e promover oportunidades intergeracionais.","meio":"Auditar critérios, divulgar formação e coorganizar atividades abertas com participação voluntária.","finalidade":"Reduzir barreiras sem impor papéis ou tarefas pela idade."},"care":"Consulte as pessoas afetadas e preserve suas escolhas; evite falar de envelhecimento só como dependência."}],"concepts":[{"title":"Etarismo","text":"Identifique julgamentos e barreiras baseados na idade, inclusive os apresentados como “naturais”."},{"title":"Autonomia","text":"Significa poder participar das decisões que afetam a própria rotina e os próprios objetivos."}],"questions":["O texto reconhece diversidade entre pessoas idosas?","A tecnologia proposta oferece alternativa acessível de atendimento?","Não confunda companhia, cuidado e substituição da autonomia."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"cultura","title":"Diversidade cultural e povos tradicionais","axis":"Educação e cultura","proposals":["Desafios para preservar o patrimônio cultural de comunidades tradicionais brasileiras","Caminhos para valorizar saberes e expressões culturais brasileiras","Participação de comunidades tradicionais nas políticas culturais"],"keywords":["cultura","patrimônio cultural","povos tradicionais","povos indígenas","afro-brasileiro","museu","identidade cultural"],"routes":[{"id":"participacao-cultural","label":"Preservação com participação","thesis":"A preservação do patrimônio cultural pode produzir apagamento quando decisões são tomadas sem participação das comunidades que mantêm práticas, memórias e saberes.","arguments":[{"claim":"Registros institucionais podem privilegiar a visão de quem documenta.","reason":"Sem consentimento e contexto, uma prática cultural pode ser transformada em objeto exótico separado de seus guardiões.","example":"Um projeto de memória pode acordar previamente com a comunidade o que registrar, como guardar e o que não divulgar.","question":"Quem decide sobre o registro, o acesso e a circulação do material?"},{"claim":"Falta de apoio contínuo fragiliza a transmissão entre gerações.","reason":"Espaços, tempo e reconhecimento são necessários para que mestres e aprendizes compartilhem práticas.","example":"Uma iniciativa local pode organizar oficinas conduzidas por representantes escolhidos pela própria comunidade.","question":"A ação tem continuidade e reconhece a autoria de quem ensina?"}],"intervention":{"agente":"Gestores de políticas culturais, junto às comunidades","acao":"Financiar iniciativas de preservação desenhadas pelos próprios grupos.","meio":"Criar editais acessíveis, assegurar consulta e prever regras de consentimento e guarda dos registros.","finalidade":"Fortalecer a continuidade cultural com autoria e participação comunitária."},"care":"Não descreva um povo como homogêneo nem publique saberes que a comunidade não deseja compartilhar."},{"id":"acesso-cultural","label":"Acesso e circulação cultural","thesis":"A desigualdade de acesso a equipamentos e de reconhecimento de diferentes expressões culturais restringe a participação e a circulação de obras.","arguments":[{"claim":"Equipamentos culturais concentrados em algumas áreas aumentam custo e tempo de acesso.","reason":"Transporte, horários e preço podem limitar quem usufrui de programação pública.","example":"Um mapa de localização, horários e itinerários pode orientar um circuito de atividades culturais gratuitas.","question":"A atividade é acessível também para quem mora longe ou tem mobilidade reduzida?"},{"claim":"Pouca presença de autores e artistas diversos em programações reduz visibilidade.","reason":"Curadoria sem diálogo pode repetir hierarquias e deixar expressões locais de fora.","example":"Uma comissão comunitária pode propor programação e critérios de seleção transparentes.","question":"Quem escolheu os artistas e como o processo foi divulgado?"}],"intervention":{"agente":"Secretarias de Cultura e equipamentos públicos","acao":"Ampliar circulação e participação na programação cultural local.","meio":"Combinar atividades itinerantes, critérios públicos de seleção e consulta a grupos de diferentes territórios.","finalidade":"Aproximar equipamentos e expressões culturais de públicos diversos."},"care":"Valorizar não é apropriar: indique autoria, contexto e consentimento."}],"concepts":[{"title":"Patrimônio cultural","text":"Pode envolver práticas, celebrações, saberes, memórias e expressões preservadas por comunidades."},{"title":"Autodeterminação e consentimento","text":"As comunidades devem influenciar como são representadas e como registros circulam."}],"questions":["Quem é responsável por definir o que preservar?","A proposta oferece autoria e continuidade à comunidade?","Evite generalizações culturais ou datas históricas sem conferir a fonte."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"fome","title":"Segurança alimentar e desigualdade","axis":"Cidadania e sociedade","proposals":["Caminhos para garantir segurança alimentar à população brasileira","Desafios para ampliar o acesso regular a alimentos adequados","Desperdício, distribuição e acesso à alimentação no Brasil"],"keywords":["insegurança alimentar","fome","alimentação","desperdício","renda","agricultura","merenda"],"routes":[{"id":"acesso-regular","label":"Renda e acesso regular","thesis":"A insegurança alimentar está ligada a condições materiais e a redes de abastecimento desiguais, o que torna insuficiente tratar a fome como escolha individual.","arguments":[{"claim":"Variação de renda e custo dos alimentos pode comprometer a regularidade do acesso.","reason":"Famílias com orçamento restrito têm menos margem para absorver aumentos ou imprevistos.","example":"Uma análise de orçamento familiar hipotético pode comparar gastos essenciais sem fingir que mede uma população real.","question":"Que recurso e que preço sustentam sua afirmação sobre acesso?"},{"claim":"A oferta local e a distância de pontos de abastecimento afetam escolhas possíveis.","reason":"Estar perto de alimentos adequados e conseguir transportá-los influenciam a rotina.","example":"Um mapa de feira, mercado e transporte pode revelar lacunas de acesso em determinado bairro.","question":"A disponibilidade está no território e no horário de que a família precisa?"}],"intervention":{"agente":"Gestores de assistência social e abastecimento, em cooperação local","acao":"Ampliar acesso estável a alimentos e informações sobre apoio disponível.","meio":"Mapear áreas atendidas, coordenar serviços locais e acompanhar regularidade com famílias participantes.","finalidade":"Reduzir interrupções no acesso e melhorar a segurança alimentar."},"care":"Não reduza pobreza alimentar a falta de educação nutricional nem recomende dietas como resposta estrutural."},{"id":"desperdicio","label":"Produção, perdas e distribuição","thesis":"Perdas evitáveis e dificuldades de coordenação entre produção, comércio e instituições podem coexistir com barreiras de acesso a alimentos.","arguments":[{"claim":"A logística e o armazenamento inadequados podem contribuir para perdas.","reason":"Distância, refrigeração e planejamento interferem na capacidade de preservar produtos.","example":"Uma cooperativa pode registrar perdas em etapas distintas antes de escolher uma solução de armazenagem.","question":"Em qual etapa a perda foi observada e qual causa pode ser corrigida?"},{"claim":"Doação pontual não substitui acesso regular nem resolve a distribuição desigual.","reason":"Ações emergenciais respondem a uma necessidade imediata, enquanto políticas de renda e abastecimento atuam na continuidade.","example":"Um banco de alimentos pode definir critérios transparentes e acompanhar origem e destino dos produtos.","question":"A medida complementa uma política contínua ou ocupa o lugar dela?"}],"intervention":{"agente":"Redes locais de abastecimento e assistência social","acao":"Melhorar a coordenação contra perdas e fortalecer o encaminhamento alimentar.","meio":"Registrar perdas, firmar acordos com segurança sanitária e divulgar de forma acessível os canais públicos existentes.","finalidade":"Aproveitar alimentos em condições adequadas e apoiar o acesso regular."},"care":"Segurança sanitária e dignidade das famílias precisam orientar qualquer distribuição."}],"concepts":[{"title":"Segurança alimentar","text":"Considere acesso regular, disponibilidade, adequação e estabilidade ao longo do tempo."},{"title":"Abastecimento","text":"Analise produção, armazenamento, transporte, comércio e destino dos alimentos."}],"questions":["O texto explica a origem da barreira ao acesso?","Uma ação emergencial está claramente separada da política contínua?","Atualize dados de fome com fonte, período e definição."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]},{"id":"acesso","title":"Inclusão digital e acesso à informação","axis":"Tecnologia e informação","proposals":["Desafios para ampliar a inclusão digital e o acesso qualificado à informação no Brasil","Como diminuir barreiras de acesso a serviços digitais","Inclusão digital para além da conexão à internet"],"keywords":["inclusão digital","internet","conexão","acesso digital","acessibilidade digital","serviços online","letramento digital"],"routes":[{"id":"infraestrutura","label":"Infraestrutura e território","thesis":"A exclusão digital persiste quando conectividade de qualidade, equipamentos e serviços acessíveis são distribuídos de modo desigual entre territórios e grupos.","arguments":[{"claim":"A disponibilidade de sinal não garante conexão estável e adequada para estudar ou trabalhar.","reason":"Cobertura, preço e qualidade influenciam a possibilidade de acessar serviços e conteúdos.","example":"Uma pesquisa local pode comparar sinal em pontos públicos em horários diferentes, descrevendo método e limites.","question":"Que medida de conexão importa além de dizer que “tem internet”?"},{"claim":"Serviços exclusivamente digitais podem excluir quem não dispõe de aparelho ou apoio.","reason":"Digitalizar um serviço sem alternativa não reduz a barreira para quem tem conexão instável ou deficiência.","example":"Um teste de serviço pode observar quantas etapas exigem aparelho recente ou autenticação difícil.","question":"Existe atendimento alternativo equivalente e acessível?"}],"intervention":{"agente":"Gestores públicos e provedores de conectividade","acao":"Mapear lacunas de acesso e manter alternativas acessíveis aos serviços digitais.","meio":"Ouvir territórios, priorizar conectividade pública e oferecer canais presenciais ou assistidos enquanto persistirem barreiras.","finalidade":"Ampliar acesso efetivo à informação e a serviços."},"care":"Não use acesso à internet como sinônimo de uso qualificado ou de igualdade digital."},{"id":"autonomia-digital","label":"Autonomia e acessibilidade","thesis":"Mesmo conectado, o usuário pode depender de terceiros quando serviços digitais não são compreensíveis, acessíveis ou compatíveis com suas necessidades.","arguments":[{"claim":"Interfaces confusas tornam direitos e tarefas difíceis de exercer.","reason":"Etapas obscuras e linguagem técnica aumentam erros e fazem usuários abandonarem serviços.","example":"Um grupo voluntário pode concluir uma tarefa simulada e apontar em qual etapa ficou em dúvida.","question":"A dificuldade está na habilidade do usuário ou no desenho da interface?"},{"claim":"A falta de formação prática impede aproveitar recursos disponíveis.","reason":"Orientação em contexto ajuda a avaliar fontes, proteger dados e concluir tarefas.","example":"Uma biblioteca pode oferecer atendimento para uso de serviços públicos com materiais em linguagem simples.","question":"A formação aumenta autonomia sem coletar senha ou fazer a tarefa no lugar da pessoa?"}],"intervention":{"agente":"Bibliotecas, escolas e equipes responsáveis por serviços digitais","acao":"Oferecer formação digital e revisar acessibilidade de serviços essenciais.","meio":"Realizar oficinas práticas, testar interfaces com usuários e manter apoio presencial sem exigir compartilhamento de senhas.","finalidade":"Aumentar autonomia e acesso seguro, preservando privacidade."},"care":"Não atribua exclusão apenas à “falta de habilidade”; investigue aparelho, conexão, linguagem e acessibilidade."}],"concepts":[{"title":"Inclusão digital","text":"Observe conexão, equipamento, acessibilidade, competências e condições de participação."},{"title":"Desenho centrado no usuário","text":"Testar tarefas com pessoas reais permite identificar barreiras antes da publicação."}],"questions":["Qual etapa concreta impede o acesso?","A alternativa presencial protege o mesmo direito enquanto a barreira permanece?","Não compare grupos sem definir local, período e indicador."],"sources":[{"title":"Inep · Cartilha da Redação 2026","url":"https://www.gov.br/inep/pt-br/centrais-de-conteudo/noticias/enem/enem-2026-cartilha-da-redacao-esta-disponivel"}]}]};
